import { Clock, Duration, Effect, Schema } from "effect";
import { HttpClientResponse } from "effect/http";
import { Media } from "../media.js";
import { RequestExecutor } from "./executor.js";
import { AIError, AuthenticationError, ContentPolicyError, InvalidProviderOutputError, InvalidRequestError, ProviderID, ProviderInternalError, RateLimitError, UnsupportedOperationError, } from "../schema/index.js";
export const json = (value, query) => ({
    type: "json",
    value,
    query,
});
export const multipart = (value) => ({ type: "multipart", value });
export const binary = (value, contentType, query) => ({
    type: "binary",
    value,
    contentType,
    query,
});
export const inline = (route, input) => ({ kind: "inline", id: route.id, provider: route.provider, ...input });
export const queued = (route, input) => ({ kind: "queued", id: route.id, provider: route.provider, ...input });
export const stream = (route, input) => ({ kind: "stream", id: route.id, provider: route.provider, ...input });
// ---------------------------------------------------------------------------
// Response helpers
// ---------------------------------------------------------------------------
/** Reasons a provider can report for a `failed` generation; anything it does not classify is `ProviderInternal`. */
const FAILURES = {
    InvalidRequest: InvalidRequestError,
    Authentication: AuthenticationError,
    RateLimit: RateLimitError,
    ProviderInternal: ProviderInternalError,
};
/** One protocol's route id, display name, and provider, with the decoders and errors that carry them. */
export const identity = (input) => {
    const provider = ProviderID.make(input.provider);
    const frameError = (message, body, cause) => new AIError({ reason: new InvalidProviderOutputError({ route: input.id, message, body, cause }) });
    /**
     * Read a text body while retaining the original payload and HTTP context on every downstream error. `invalid` is a
     * malformed provider document; `ended` is a generation that reached a terminal status without output (`failed`
     * carries the provider's classification, defaulting to `ProviderInternal`; `cancelled`/`expired` mean the result
     * will never exist); `pending` is a `result()` read before the generation finished, which is caller misuse;
     * `contentPolicy` is a moderated result.
     */
    const text = Effect.fn("MediaProtocol.text")(function* (response) {
        const http = RequestExecutor.responseHttp(response);
        const body = yield* response.text.pipe(Effect.mapError((cause) => new AIError({
            reason: new InvalidProviderOutputError({
                route: input.id,
                message: `Failed to read the ${input.name} response`,
                http,
                cause,
            }),
        })));
        return {
            body,
            http,
            invalid: (message, cause) => new AIError({ reason: new InvalidProviderOutputError({ route: input.id, message, body, http, cause }) }),
            ended: (status, message, failure = "ProviderInternal") => new AIError({
                reason: status === "failed"
                    ? new FAILURES[failure]({ message, body, http })
                    : new InvalidRequestError({ message, body, http }),
            }),
            pending: (id) => new AIError({
                reason: new InvalidRequestError({
                    message: `${input.name} generation ${id} has not finished; await it before reading the result`,
                    body,
                    http,
                }),
            }),
            contentPolicy: (message) => new AIError({ reason: new ContentPolicyError({ message, body, http }) }),
        };
    });
    /** Read and Schema-decode a JSON body. Decode failures keep the raw body as `reason.body`. */
    const decodeJson = (schema) => {
        const decode = Schema.decodeUnknownEffect(Schema.fromJsonString(schema));
        return Effect.fn("MediaProtocol.decodeJson")(function* (response) {
            const output = yield* text(response);
            const value = yield* decode(output.body).pipe(Effect.mapError((cause) => output.invalid(`${input.name} returned an invalid response`, cause)));
            return { ...output, value };
        });
    };
    return {
        id: input.id,
        name: input.name,
        provider,
        text,
        decodeJson,
        /** Decode a submission response into the token and first snapshot. */
        decodeStarted: (schema, started) => {
            const decode = decodeJson(schema);
            return (response) => decode(response).pipe(Effect.map((output) => started(output.value)));
        },
        /** Schema-decode one JSON stream frame. Decode failures keep the frame as `reason.body`. */
        decodeFrame: (schema) => {
            const decode = Schema.decodeUnknownEffect(Schema.fromJsonString(schema));
            return (frame) => decode(frame).pipe(Effect.mapError((cause) => frameError(`${input.name} sent an invalid stream event`, frame, cause)));
        },
        /** A stream-time failure; the frame stays on `reason.body`. */
        frameError,
        incomplete: () => new AIError({
            reason: new InvalidProviderOutputError({
                route: input.id,
                message: "The provider response ended unexpectedly.",
                classification: "incomplete-stream",
            }),
        }),
        unsupported: (operation, message) => new AIError({ reason: new UnsupportedOperationError({ operation, provider, route: input.id, message }) }),
    };
};
/** Map a provider status string through the protocol's table; unknown values are an invalid provider document. */
export const status = (table, raw, output) => {
    if (!Object.hasOwn(table, raw))
        return Effect.fail(output.invalid(`Unknown generation status "${raw}"`));
    return Effect.succeed(table[raw]);
};
/** Map a provider error code through the protocol's table; missing or unmapped codes are `ProviderInternal`. */
export const failure = (table, code) => code !== undefined && Object.hasOwn(table, code) ? table[code] : "ProviderInternal";
/** A `url` asset whose provider-declared retention window starts now. */
export const expiringUrl = (url, retention, options) => Clock.currentTimeMillis.pipe(Effect.map((now) => Media.url(url, { ...options, expiresAt: now + Duration.toMillis(retention) })));
export * as MediaProtocol from "./media-protocol.js";
